---@field MusicPlayer                   	UnityEngine.RectTransform                         
local UIActionBossCollectionNode = Class("UIActionBossCollectionNode")
function UIActionBossCollectionNode:__init()
    self._data = nil
    self._cb = nil
    self._timeDown = nil
end

function UIActionBossCollectionNode:__delete()
    self._data = nil
    self._cb = nil
    self._timeDown = nil
end

function UIActionBossCollectionNode:Awake()
end

function UIActionBossCollectionNode:Start()
end

function UIActionBossCollectionNode:Refresh(data, ind)
    if not data then
        return
    end

    self._data = data
    self:FillSelf()

    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        local data = ActionUtils.GetAnnihilationInfo(self._data.regionBelong)
        local isOpen = ActionUtils.IsOpenAnnihilation(self._data.regionBelong)
        --已开启
        if isOpen then
            CfUtils.FillText(self.TxtTime, CfUtils.GetTimeHMS(checkNumber(data.remainTime)))
        else
            self:FillSelf()
            if not isNull(self._timeDown) then
                CDTimerModule.GetInstance():RemoveCD(self._timeDown)
                self._timeDown = nil
            end
        end
    end, CountDownTime, false, true)

    CfUtils.SetActive(self.NormalGroup.transform:Find("ImgBg2/ImgLeftUp"), ind == 1)
    CfUtils.SetActive(self.NormalGroup.transform:Find("ImgBg2/ImgLeftDown"), ind == 1)
end

function UIActionBossCollectionNode:FillSelf()
    local id = ActionUtils.GetBossRegionPointId(self._data.regionBelong)
    local isUnlock, err = ActionUtils.IsUnlockRegionalSecondPoint(id)
    local isFinish = ActionUtils.IsFinishAnnihilation(self._data.regionBelong)

    CfUtils.SetUISwitchImage(self.ImgSlider, 1)

    local data = ActionUtils.GetAnnihilationInfo(self._data.regionBelong)
    if data then
        self.ImgSlider.fillAmount = checkNumber(data.progress)
        CfUtils.FillText(self.TxtProgress, localize("_num_<size=22>%</size>", {_num_ = checkInt(checkNumber(data.progress) * 100)}))
    end

    local isUnlockAnnihilation = ActionUtils.IsUnlockAnnihilation()
    CfUtils.SetActive(self.TxtProgress, isUnlockAnnihilation)

    CfUtils.FillText(self.TxtName, self._data.label)

    local vo = ActionUtils.GetRegionPrimaryMapVo(self._data.regionBelong)
    CfUtils.FillImage(self.ImgBg, vo.OverviewBanner)

    CfUtils.SetActive(self.LockGroup, false)
    CfUtils.SetActive(self.FinishGroup, false)
    CfUtils.SetActive(self.DestoryGroup, false)

    local isOpen = ActionUtils.IsOpenAnnihilation(self._data.regionBelong)
    CfUtils.SetActive(self.ImgSlider, not isOpen)
    CfUtils.SetActive(self.TxtName, not isOpen)
    CfUtils.SetActive(self.TxtProgress, not isOpen and isUnlockAnnihilation)
    CfUtils.SetActive(self.NormalGroup.transform:Find("ImgSliderFrame"), not isOpen)

    if isUnlock then
        --已结束
        if isFinish then
            CfUtils.SetActive(self.FinishGroup, true)
            CfUtils.SetActive(self.TxtProgress, false)
            CfUtils.SetActive(self.ImgSlider, false)
        else
            --已开启
            if isOpen then
                CfUtils.SetActive(self.DestoryGroup, true)
                CfUtils.FillText(self.TxtTime, CfUtils.GetTimeHMS(checkNumber(data.remainTime)))
                local vo = ActionUtils.GetRegionAnnihilationTypeVo(data.bossTypeId)
                if vo then
                    CfUtils.FillImage(self.ImgMonster, vo.bossPortrait2)
                    CfUtils.FillImage(self.ImgMonster2, vo.bossPortrait2)
                    CfUtils.FillImage(self.ImgMonster3, vo.bossPortrait2)
                end
                self.ImgSlider.fillAmount = 1
                CfUtils.FillText(self.TxtProgress, localize("_num_<size=22>%</size>", {_num_ = 100}))
                CfUtils.FillText(self.AnimRoot.transform:Find("DestoryGroup/TxtName"), self._data.label)

            end
            CfUtils.SetActive(self.TxtProgress, true)
        end
    else
        CfUtils.SetActive(self.LockGroup, true)
        CfUtils.FillText(self.TxtName2, err)
        CfUtils.SetActive(self.TxtProgress, false)
    end
end

function UIActionBossCollectionNode:OnBtnClick()
    if not self._cb then
        self._cb()
    end
end

function UIActionBossCollectionNode:OnDestroy()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end

    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIActionBossCollectionNode